// GENERATED by pi-cache/scripts/sync-lookahead-rule.mjs from services/enc/chartDatum.ts.
/** Chart sounding datums, not height/bridge-clearance datums.
 * IHO S-57 UOC ed4.4 sections 2.1.2-2.1.3, tables2.1/2.2:
 * https://iho.int/uploads/user/pubs/standards/s-57/S-57%20Appendix%20B.1%20Annex%20A_Ed%204.4.0_FINAL.pdf
 * 12=MLLW, 23=LAT, 27=LLWLT. Approximate datums are NOT equivalents.
 * All inputs/derived values stay in memory, including for licensed cells. */
import type { EncConversionResult } from './types.js';

export type SoundingDatum = 'LAT' | 'MLLW' | 'LLWLT' | 'MSL';
export type ChartBounds = [number, number, number, number];

/** Producer fallback from130-01: no producer-wide entry was implemented in
 * the inherited source. Candidates in the roadmap are not evidence. Keep
 * this empty until national notes prove every cell uses the same datum.
 * Explicit unknown/other cell metadata NEVER falls through to this table. */
export const VERIFIED_PRODUCER_DATUMS: ReadonlyMap<string, SoundingDatum> = new Map();

export function normalizeSoundingDatum(raw: unknown): SoundingDatum | null {
    if (typeof raw === 'number' || (typeof raw === 'string' && /^\d+$/.test(raw.trim()))) {
        return ({ 3: 'MSL', 12: 'MLLW', 23: 'LAT', 27: 'LLWLT' } as const)[Number(raw) as 3 | 12 | 23 | 27] ?? null;
    }
    if (typeof raw !== 'string') return null;
    const value = raw.trim().toUpperCase().replace(/[._-]/g, ' ').replace(/\s+/g, ' ');
    const names: Readonly<Record<string, SoundingDatum>> = {
        LAT: 'LAT',
        'LOWEST ASTRONOMICAL TIDE': 'LAT',
        MLLW: 'MLLW',
        'MEAN LOWER LOW WATER': 'MLLW',
        LLWLT: 'LLWLT',
        'LOWER LOW WATER LARGE TIDE': 'LLWLT',
        MSL: 'MSL',
        'MEAN SEA LEVEL': 'MSL',
    };
    return names[value] ?? null;
}

/** Whole-cell proof, deliberately conservative for a single offset applied
 * to many chart objects. Every local M_SDAT override must match its default.
 * A failed/partial extraction has no M_SDAT key and can never look complete.
 * VDAT is retained for future overhead-clearance work, never used here. */
export function cellSoundingDatum(cell: EncConversionResult): SoundingDatum | null {
    const defaultDatum =
        cell.soundingDatum === undefined
            ? (VERIFIED_PRODUCER_DATUMS.get(cell.sourceHO) ?? null)
            : normalizeSoundingDatum(cell.soundingDatum);
    if (!defaultDatum) return null;
    if (!Number.isSafeInteger(cell.extractorSchema) || (cell.extractorSchema ?? 1) < 3) return null;
    const zones = cell.layers.M_SDAT;
    if (!zones || zones.type !== 'FeatureCollection' || !Array.isArray(zones.features)) return null;
    for (const zone of zones.features) {
        if (!zone || zone.type !== 'Feature') return null;
        const p = zone.properties;
        if (!validDatumArea(zone.geometry)) return null;
        if (normalizeSoundingDatum(p?.VERDAT ?? p?.verdat) !== defaultDatum) return null;
    }
    return defaultDatum;
}

function validDatumArea(geometry: GeoJSON.Geometry | null): boolean {
    const polygons =
        geometry?.type === 'Polygon'
            ? [geometry.coordinates]
            : geometry?.type === 'MultiPolygon'
              ? geometry.coordinates
              : null;
    return (
        !!polygons &&
        polygons.length > 0 &&
        polygons.every(
            (polygon) =>
                polygon.length > 0 &&
                polygon.every((ring) => {
                    if (
                        ring.length < 4 ||
                        !ring.every((p) => p.length >= 2 && Number.isFinite(p[0]) && Number.isFinite(p[1]))
                    )
                        return false;
                    const first = ring[0],
                        last = ring[ring.length - 1];
                    return first[0] === last[0] && first[1] === last[1];
                }),
        )
    );
}

export function matchingSoundingDatum(cells: readonly EncConversionResult[]): SoundingDatum | null {
    if (cells.length === 0) return null;
    const datum = cellSoundingDatum(cells[0]);
    return datum && cells.every((cell) => cellSoundingDatum(cell) === datum) ? datum : null;
}

export function chartAndCurveDatumsMatch(chart: unknown, curve: unknown): boolean {
    const datum = normalizeSoundingDatum(chart);
    return datum !== null && datum === normalizeSoundingDatum(curve);
}
